CREATE INDEX IF NOT EXISTS classifieds_photo_handoff_due ON classifieds_records (coalesce(json_extract(body, '$.dueAt'), 0), id) WHERE kind = 'adCleanup' AND json_extract(body, '$.stage') = 'handoff' AND coalesce(json_extract(body, '$.status'), 'pending') NOT IN ('completed', 'success');
CREATE INDEX IF NOT EXISTS classifieds_photo_individual_deletion_due ON classifieds_records (coalesce(json_extract(body, '$.dueAt'), 0), kind, id) WHERE kind IN ('adCleanup', 'photoCleanup') AND coalesce(json_extract(body, '$.stage'), '') != 'handoff' AND coalesce(json_extract(body, '$.status'), 'pending') NOT IN ('completed', 'success');
